def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    dangerous_prev = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    dangerous_prev.append(bid)

    if budget <= 0:
        return 0.0

    units = supply / float(WATER_REQ)
    high_supply = units >= 1.8
    low_supply = units <= 1.3

    highest_prev = max(prev_bids) if prev_bids else 0.0
    pressure_bid = max(dangerous_prev) if dangerous_prev else highest_prev

    urgency = 0
    if hp <= 3:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 1:
        urgency += 2
    if low_supply:
        urgency += 1
    if day >= 8:
        urgency += 1

    if not alive_opponents:
        if urgency >= 2:
            bid = DAILY_SALARY * 0.55
        else:
            bid = DAILY_SALARY * 0.2
        return float(max(0.0, min(budget, bid)))

    if urgency >= 4:
        bid = max(DAILY_SALARY * 0.92, pressure_bid + 2.5)
    elif urgency >= 2:
        bid = max(DAILY_SALARY * 0.72, pressure_bid + 1.5)
    else:
        if high_supply and highest_prev >= DAILY_SALARY * 0.85:
            bid = DAILY_SALARY * 0.22
        elif high_supply:
            bid = max(DAILY_SALARY * 0.35, pressure_bid * 0.72)
        elif low_supply:
            bid = max(DAILY_SALARY * 0.62, pressure_bid + 1.0)
        else:
            bid = max(DAILY_SALARY * 0.48, pressure_bid * 0.9)

    if budget < DAILY_SALARY * 0.5 and urgency <= 1:
        bid = min(bid, budget * 0.55)
    elif budget < DAILY_SALARY and urgency <= 2:
        bid = min(bid, budget * 0.8)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.97))

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    available_slots = int(day_context['supply'] // WATER_REQ)

    # Base bid - a moderate starting point
    base_bid = DAILY_SALARY * 0.65 # 58.5

    # Survival mode: If HP is very low, bid very aggressively
    if my_status['hp'] <= 1:
        return min(my_status['budget'], DAILY_SALARY * 0.99)
    # If HP is low, bid aggressively
    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    # Late game aggression: If it's towards the end and HP is not full
    if day_context['day'] >= EPISODE_DAYS - 2 and my_status['hp'] < 10:
        if my_status['hp'] <= 5:
            return min(my_status['budget'], DAILY_SALARY * 0.95)
        else:
            base_bid = DAILY_SALARY * 0.8 # Increase base bid for late game

    # Analyze yesterday's bids from opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Handle cases with no previous bids or no active opponents
    if not yesterday_bids:
        if num_alive_opponents == 0:
            return min(my_status['budget'], DAILY_SALARY * 0.1) # Bid low if no competition
        else:
            return min(my_status['budget'], base_bid) # Use base bid if opponents exist but no trace

    highest_prev_bid = max(yesterday_bids)
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

    # Define aggression thresholds based on DAILY_SALARY
    AGGRESSIVE_THRESHOLD = DAILY_SALARY * 0.8 # 72
    VERY_AGGRESSIVE_THRESHOLD = DAILY_SALARY * 0.9 # 81

    # Determine competition level: high competition if more active opponents than available water slots
    high_competition = num_alive_opponents > available_slots

    if highest_prev_bid > VERY_AGGRESSIVE_THRESHOLD: # Opponents are bidding very high
        if my_status['hp'] > 7 and not high_competition: # Very good HP, and less competition
            # Can afford to bid a bit lower to save budget, but still competitive
            return min(my_status['budget'], DAILY_SALARY * 0.75)
        else: # HP is not very good, or competition is high, need to be very competitive
            return min(my_status['budget'], highest_prev_bid + 2, DAILY_SALARY * 0.98)

    elif highest_prev_bid > AGGRESSIVE_THRESHOLD: # Opponents are aggressive
        if high_competition:
            return min(my_status['budget'], highest_prev_bid + 1.5, DAILY_SALARY * 0.92)
        else: # Less competition, slightly less aggressive but still aim to win
            return min(my_status['budget'], highest_prev_bid + 1, DAILY_SALARY * 0.85)

    else: # Opponents are bidding moderately
        if high_competition:
            return min(my_status['budget'], max(base_bid, avg_prev_bid + 1), DAILY_SALARY * 0.78)
        else: # Less competition, more conservative
            return min(my_status['budget'], max(base_bid, avg_prev_bid + 0.5), DAILY_SALARY * 0.7)

    # Fallback (should be covered by conditions above, but good practice)
    return min(my_status['budget'], base_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents alive, conserve budget.
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction.
    prev_bids = []
    for _, o in alive_opps:
        pt = o.get('previous_trace', None) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how many water units are likely available.
    # Use supply/WATER_REQ but keep it robust.
    units_est = int(max(0, supply / float(WATER_REQ)))
    if units_est <= 0:
        units_est = 1

    # Determine a target bid based on yesterday's competitive pressure.
    # Observed: Alex avg ~76, David avg ~62; Bob avg ~34 died; Eric bid 0 died.
    # So aim above the mid tier but below the top tier.
    if prev_bids:
        highest_prev = max(prev_bids)
        second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
    else:
        highest_prev = 0.0
        second_prev = 0.0

    # Base pressure level.
    # If someone bid very high yesterday, increase; else keep moderate.
    if highest_prev >= DAILY_SALARY * 0.7:
        pressure = 0.85
    elif highest_prev >= DAILY_SALARY * 0.45:
        pressure = 0.65
    else:
        pressure = 0.55

    # HP-based risk adjustment.
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])
    if hp <= 2 or no_water_days >= 2:
        hp_factor = 0.95
    elif hp <= 4:
        hp_factor = 0.80
    else:
        hp_factor = 0.65

    # Supply adjustment: lower supply => bid more to secure water.
    if supply <= float(MIN_SUPPLY) + 1e-9:
        supply_factor = 0.95
    elif supply <= float(MIN_SUPPLY) + 5:
        supply_factor = 0.80
    else:
        supply_factor = 0.65

    # Compute a candidate bid.
    # Anchor around mid/high yesterday bids, but cap to avoid overbidding.
    anchor = max(second_prev, highest_prev * 0.75, DAILY_SALARY * 0.45)
    candidate = anchor * pressure * hp_factor * supply_factor

    # Ensure we bid enough relative to competition, but not exceed budget.
    # Also keep a floor to avoid the '0 bid' failure pattern.
    floor_bid = DAILY_SALARY * 0.35
    cap_bid = DAILY_SALARY * 0.95

    bid = max(floor_bid, min(cap_bid, candidate))

    # If budget is low, scale down proportionally.
    budget = float(my_status['budget'])
    if budget <= 0:
        return 0.0

    # Avoid bidding more than budget.
    bid = min(bid, budget)

    # If we have very low budget, still try to survive: bid a fraction.
    if budget < DAILY_SALARY * 0.5:
        bid = min(bid, budget * 0.9)

    # Final sanity: non-negative.
    if bid < 0:
        bid = 0.0
    return float(bid)
